<script setup lang="ts">
import { apiPath } from '@/utils/api'
import { Plus, Search, Pencil, Trash2 } from 'lucide-vue-next'
import { Button } from '@/components/ui/button'
import { Card, CardContent } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Select } from '@/components/ui/select'
import type { GisLocation, Category } from '@/types/gis'
definePageMeta({middleware:'admin',layout:'admin'})
const q=ref('');const category=ref('');const condition=ref('');const page=ref(1)
const {data:cats}=await useFetch<{items:Category[]}>(apiPath('/api/admin/categories'),{default:()=>({items:[]})})
const query=computed(()=>({q:q.value,category:category.value,condition:condition.value,page:page.value,limit:30}))
const {data,refresh,pending}=await useFetch<{items:GisLocation[];total:number;page:number;pages:number}>(apiPath('/api/admin/locations'),{query,watch:[query],default:()=>({items:[],total:0,page:1,pages:1})})
async function remove(id:number){if(!confirm('Hapus lokasi ini?'))return;await $fetch(apiPath(`/api/admin/locations/${id}`),{method:'DELETE'});await refresh()}
</script>
<template><div class="space-y-5"><div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h1 class="text-2xl font-bold tracking-tight">Locations</h1><p class="mt-1 text-sm text-muted-foreground">{{data.total.toLocaleString('id-ID')}} record GIS.</p></div><NuxtLink to="/admin/locations/new"><Button><Plus class="size-4" />Tambah lokasi</Button></NuxtLink></div><Card><CardContent class="p-4"><div class="grid gap-3 md:grid-cols-[1fr_220px_220px]"><div class="relative"><Search class="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input v-model="q" class="pl-9" placeholder="Cari lokasi..." /></div><Select v-model="category"><option value="">Semua kategori</option><option v-for="cat in cats.items" :key="cat.id" :value="cat.slug">{{cat.name}}</option></Select><Select v-model="condition"><option value="">Semua kondisi</option><option value="good">Baik</option><option value="bad">Tidak Baik</option><option value="unassessed">Belum Dinilai</option></Select></div></CardContent></Card><div class="overflow-hidden rounded-xl border bg-card"><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="border-b bg-muted/50 text-left text-xs text-muted-foreground"><tr><th class="px-4 py-3">Lokasi</th><th class="px-4 py-3">Kategori</th><th class="px-4 py-3">Kecamatan</th><th class="px-4 py-3">Kondisi</th><th class="px-4 py-3 text-right">Aksi</th></tr></thead><tbody><tr v-if="pending"><td colspan="5" class="p-8 text-center text-muted-foreground">Memuat...</td></tr><tr v-for="item in data.items" :key="item.id" class="border-b last:border-0"><td class="px-4 py-3"><div class="font-medium">{{item.name}}</div><div class="text-xs text-muted-foreground">{{item.latitude.toFixed(5)}}, {{item.longitude.toFixed(5)}}</div></td><td class="px-4 py-3">{{item.category_name}}</td><td class="px-4 py-3">{{item.district||'—'}}</td><td class="px-4 py-3"><ConditionBadge :condition="item.condition" /></td><td class="px-4 py-3"><div class="flex justify-end gap-1"><NuxtLink :to="`/admin/locations/${item.id}`"><Button variant="ghost" size="icon"><Pencil class="size-4" /></Button></NuxtLink><Button variant="ghost" size="icon" @click="remove(item.id)"><Trash2 class="size-4 text-destructive" /></Button></div></td></tr><tr v-if="!pending&&!data.items.length"><td colspan="5" class="p-10 text-center text-muted-foreground">Belum ada data yang cocok.</td></tr></tbody></table></div></div><div class="flex items-center justify-between"><div class="text-xs text-muted-foreground">Halaman {{data.page}} / {{data.pages}}</div><div class="flex gap-2"><Button variant="outline" size="sm" :disabled="page<=1" @click="page--">Sebelumnya</Button><Button variant="outline" size="sm" :disabled="page>=data.pages" @click="page++">Berikutnya</Button></div></div></div></template>
